'use strict';
window.VocabularyHub=(()=>{
 const defaults=[['general','General'],['background','Nationality, Background & Location'],['occupations','Names & Occupations'],['family','Family'],['computer','Using Computer']];let tab='home',topic='',query='',page=1,selectedDate='';
 function normalize(raw){const topics=[],ids=new Set();for(const t of[...defaults.map(([id,name])=>({id,name})),...(Array.isArray(raw?.topics)?raw.topics:[])]){if(!t||typeof t.id!=='string'||typeof t.name!=='string'||!t.name.trim())continue;if(ids.has(t.id)){topics.find(x=>x.id===t.id).name=t.name.trim().slice(0,150);continue}ids.add(t.id);topics.push({id:t.id,name:t.name.trim().slice(0,150)})}return{topics,assignments:Object.fromEntries(Object.entries(raw?.assignments||{}).filter(([id,t])=>typeof id==='string'&&ids.has(t)))}}
 function config(){return state.vocabularyGroups=normalize(state.vocabularyGroups)}
 function infer(w){if(/가족|아버지|어머니|부모|형제|언니|누나|오빠|동생|남편|아내|할머니|할아버지|외동|친척|닮다/.test(w.korean))return'family';if(/교사|수의사|간호사|변호사|회계사|공무원|연구원|은행원|음악가|작곡가|작가|화가|예술가|사업가|경찰관|소방관|전문가|군인|성함|이름/.test(w.korean))return'occupations';if(w.studyRef?.chapter===1&&/^(grammar|vocabulary|quiz|conversation)-1$/.test(w.studyRef.part))return'background';if(w.studyRef?.chapter===1&&/^(grammar|vocabulary|quiz|conversation)-2$/.test(w.studyRef.part))return'occupations';return'general'}
 function topicOf(w){const c=config();return c.assignments[w.id]||infer(w)}
 function assign(id,value){const c=config();c.assignments[id]=c.topics.some(t=>t.id===value)?value:'general'}
 function dateOf(w){return w.addedAt&&Number.isFinite(Date.parse(w.addedAt))?new Date(w.addedAt).toLocaleDateString('en-CA',{timeZone:'Asia/Dubai'}):w.studyRef.date}
 function matches(w,stack){if(w.deleted||w.hanjaRef||w.studyRef?.kind==='grammar')return false;const key=stack.slice(6);if(key==='topik')return !w.studyRef;if(key==='book')return !!w.studyRef;if(key==='mixed')return true;if(key.startsWith('topic:'))return !!w.studyRef&&topicOf(w)===key.slice(6);if(key.startsWith('day:'))return !!w.studyRef&&(dateOf(w))===key.slice(4);return false}
 function pool(group='book'){return words.filter(w=>matches(w,'Vocab:'+group))}
 function options(selected='general'){return config().topics.map(t=>`<option value="${e(t.id)}" ${selected===t.id?'selected':''}>${e(t.name)}</option>`).join('')}
 function open(next='home',id=''){tab=next;topic=id;query='';page=1;window.StudyHub.open('vocabulary')}
 function label(stack){const key=stack.slice(6);return key==='topik'?'TOPIK I vocabulary':key==='book'?'Korean Made Easy vocabulary':key==='mixed'?'All words mixed':key.startsWith('topic:')?config().topics.find(t=>t.id===key.slice(6))?.name||'Vocabulary':key.startsWith('day:')?'Latest vocabulary · '+key.slice(4):'Vocabulary'}
 function practiceButtons(stack){return`<div class="hub-actions">${[['cards','Flashcards'],['quiz','Quiz'],['typing','Type Korean'],['library','Word list']].map(([mode,label])=>`<button class="${mode==='cards'?'btn primary':'small-btn'}" data-vocab-practice="${e(stack)}" data-practice-kind="${mode}">${label}</button>`).join('')}</div>`}
 function editTopic(id){const old=config().topics.find(t=>t.id===id);showDialog(`<h2>${old?'Edit category':'Add category'}</h2><form id="topicForm"><label for="topicName">Category name</label><input id="topicName" maxlength="150" required value="${e(old?.name||'')}"><button class="btn primary" type="submit">Save category</button></form>`);$('#topicForm').onsubmit=ev=>{ev.preventDefault();const name=$('#topicName').value.trim();if(!name)return;const c=config();if(old)c.topics.find(t=>t.id===id).name=name;else c.topics.push({id:'topic-'+crypto.randomUUID(),name});save();$('#dialog').close();render()}}
 function render(){const c=config(),book=pool('book'),topik=pool('topik'),all=pool('mixed'),dates=[...new Set(book.map(w=>dateOf(w)))].sort().reverse();if(!dates.includes(selectedDate))selectedDate=dates[0]||today();const tabs=[['home','Overview'],['topik','TOPIK I'],['book','Korean Made Easy'],['mixed','All words mixed'],['latest','Latest added']];let html=`<nav class="hub-nav vocab-tabs" aria-label="Vocabulary sections">${tabs.map(([key,label])=>`<button class="small-btn ${tab===key?'selected':''}" data-vocab-tab="${key}" aria-pressed="${tab===key}">${label}</button>`).join('')}</nav>`;
 if(tab==='home'){html+=`<div class="vocab-stats">${[[topik.length,'TOPIK I'],[book.length,'Korean Made Easy'],[all.filter(learned).length,'Learned words']].map(([n,label])=>`<article><strong>${n}</strong><span>${label}</span></article>`).join('')}</div><div class="reference-grid vocab-shortcuts">${[['topik','TOPIK I vocabulary','Your original exam cards'],['book','Korean Made Easy','Chapter vocabulary & topics'],['latest','Latest added','Your newest study words']].map(([key,title,text])=>`<button class="topic-tile" data-vocab-tab="${key}"><strong>${title}</strong><span>${text}</span><span>Open →</span></button>`).join('')}</div><h2>TOPIK I practice</h2>${practiceButtons('Vocab:topik').replace('>Flashcards<','>TOPIK I flashcards<')}<h2>Topics</h2>`}
 if(tab==='home'||tab==='book'){html+=`${tab==='book'?practiceButtons('Vocab:book'):''}<div class="reference-toolbar"><label class="reference-search" for="topicSearch"><span>Search categories</span><input id="topicSearch" type="search" value="${e(query)}" placeholder="Search categories"></label><button class="btn primary" id="addVocabTopic">Add category</button></div>`;const filtered=c.topics.filter(t=>t.name.toLocaleLowerCase().includes(query.toLocaleLowerCase())),total=Math.max(1,Math.ceil(filtered.length/9));page=Math.min(page,total);html+=`<div class="reference-grid">${filtered.slice((page-1)*9,page*9).map(t=>`<article class="reference-card topic-card"><button class="topic-tile" data-open-topic="${e(t.id)}"><strong translate="no">${e(t.name)}</strong><span>${book.filter(w=>topicOf(w)===t.id).length} words</span></button><div class="reference-card-actions"><button class="small-btn" data-edit-topic="${e(t.id)}">Edit category</button><button class="text-link" data-topic-cards="${e(t.id)}">Flashcards</button></div></article>`).join('')||'<p>No matching entries.</p>'}</div><div class="reference-pagination"><button class="small-btn" id="topicsPrev" ${page<=1?'disabled':''}>Previous</button><span>PAGE ${page} / ${total}</span><button class="small-btn" id="topicsNext" ${page>=total?'disabled':''}>Next</button></div>`}
 if(tab==='topik'){html+=`<h2>TOPIK I vocabulary</h2>${practiceButtons('Vocab:topik')}<details class="hub-card"><summary>Original categories</summary><div class="hub-actions">${[...new Set(['IMPORTANT WORDS','Learned words','My mistakes','Forgotten after learning','Synonyms','Antonyms','Word families',...topik.flatMap(w=>w.categories)])].map(name=>`<button class="small-btn" data-old-stack="${e(name)}">${e(name)}</button>`).join('')}</div></details>`;html+=wordList(topik)}
 if(tab==='mixed'){html+=practiceButtons('Vocab:mixed')+wordList(all)}
 if(tab==='latest'){html+=`<label class="session-field">Added on<select id="vocabDate">${dates.map(date=>`<option value="${date}" ${selectedDate===date?'selected':''}>${date}</option>`).join('')||`<option>${today()}</option>`}</select></label>${practiceButtons('Vocab:day:'+selectedDate)}${wordList(pool('day:'+selectedDate))}`}
 if(tab==='topic'){const t=c.topics.find(t=>t.id===topic)||c.topics[0];html+=`<button class="text-link" id="backToTopics">← Categories</button><h2 translate="no">${e(t.name)}</h2>${practiceButtons('Vocab:topic:'+t.id)}${wordList(pool('topic:'+t.id))}`}
 $('#hubBody').innerHTML=html;document.querySelectorAll('[data-vocab-tab]').forEach(b=>b.onclick=()=>open(b.dataset.vocabTab));document.querySelectorAll('[data-vocab-practice]').forEach(b=>b.onclick=()=>window.StudyHub.startPractice(b.dataset.vocabPractice,b.dataset.practiceKind));document.querySelectorAll('[data-old-stack]').forEach(b=>b.onclick=()=>window.StudyHub.startPractice(b.dataset.oldStack,['Synonyms','Antonyms'].includes(b.dataset.oldStack)?'links':'cards'));document.querySelectorAll('[data-open-topic]').forEach(b=>b.onclick=()=>open('topic',b.dataset.openTopic));document.querySelectorAll('[data-edit-topic]').forEach(b=>b.onclick=()=>editTopic(b.dataset.editTopic));document.querySelectorAll('[data-topic-cards]').forEach(b=>b.onclick=()=>window.StudyHub.openStack('Vocab:topic:'+b.dataset.topicCards));document.querySelectorAll('[data-vocab-edit]').forEach(b=>b.onclick=()=>window.Vocabulary.edit(b.dataset.vocabEdit));document.querySelectorAll('[data-word-topic]').forEach(input=>input.onchange=()=>{assign(input.dataset.wordTopic,input.value);save()});if($('#backToTopics'))$('#backToTopics').onclick=()=>open('book');if($('#addVocabTopic'))$('#addVocabTopic').onclick=()=>editTopic();if($('#topicSearch'))$('#topicSearch').oninput=ev=>{query=ev.target.value;page=1;render();$('#topicSearch').focus()};if($('#topicsPrev'))$('#topicsPrev').onclick=()=>{page--;render()};if($('#topicsNext'))$('#topicsNext').onclick=()=>{page++;render()};if($('#vocabDate'))$('#vocabDate').onchange=ev=>{selectedDate=ev.target.value;render()};if($('#vocabWordSearch'))$('#vocabWordSearch').oninput=ev=>{query=ev.target.value;page=1;render();$('#vocabWordSearch').focus()};if($('#vocabWordPrev'))$('#vocabWordPrev').onclick=()=>{page--;render()};if($('#vocabWordNext'))$('#vocabWordNext').onclick=()=>{page++;render()}}
 function wordList(list){const q=query.toLocaleLowerCase(),filtered=list.filter(w=>(w.korean+' '+w.answer).toLocaleLowerCase().includes(q)),total=Math.max(1,Math.ceil(filtered.length/24));page=Math.min(page,total);return`<label class="reference-search" for="vocabWordSearch"><span>Search words</span><input id="vocabWordSearch" type="search" value="${e(query)}" placeholder="Search words"></label><div class="vocab-word-list">${filtered.slice((page-1)*24,page*24).map(w=>`<article class="vocab-word"><details><summary lang="ko" translate="no">${e(w.korean)} <span>${learned(w)?'✓':''}</span></summary><p translate="no">${e(w.quizAnswer||w.answer)}</p></details>${w.studyRef?`<label>Category<select data-word-topic="${e(w.id)}">${options(topicOf(w))}</select></label><small>Chapter ${w.studyRef.chapter} · ${e(w.studyRef.date)}</small>`:'<small>TOPIK I</small>'}${w.custom?`<button class="text-link" data-vocab-edit="${e(w.id)}">Edit / delete</button>`:''}</article>`).join('')||'<p>No words yet.</p>'}</div><div class="reference-pagination"><button class="small-btn" id="vocabWordPrev" ${page<=1?'disabled':''}>Previous</button><span>PAGE ${page} / ${total}</span><button class="small-btn" id="vocabWordNext" ${page>=total?'disabled':''}>Next</button></div>`}
 return{normalize,config,infer,topicOf,assign,matches,pool,options,open,label,render};
})();
